import { useEffect, useMemo, useRef, useState } from "react";
import { Search } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { CommandCatalog, RunCommand } from "../../wailsjs/go/controllers/CommandCenter";
import { useT } from "../lib/i18n";

type Command = { id: string; title: string; group: string; hint?: string; keywords?: string[] };

// The Ctrl+K palette: fuzzy filter over the backend command catalog,
// Enter runs the highlighted intent. Pane-creating intents come back as
// commandcenter:run events the shell executes (it owns the workspace).
export default function CommandPalette({
  open,
  onClose,
  onNavigate,
}: {
  open: boolean;
  onClose: () => void;
  onNavigate: (target: string) => void;
}) {
  const t = useT();
  const [query, setQuery] = useState("");
  const [commands, setCommands] = useState<Command[]>([]);
  const [selected, setSelected] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    // Deferred resets/loads so no setState runs synchronously in the
    // effect body.
    const timer = setTimeout(() => {
      setQuery("");
      setSelected(0);
      CommandCatalog()
        .then((list: Command[]) => setCommands(list ?? []))
        .catch(() => setCommands([]));
      inputRef.current?.focus();
    }, 0);
    return () => clearTimeout(timer);
  }, [open]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return commands.slice(0, 30);
    const score = (cmd: Command) => {
      const haystack = [cmd.title, cmd.hint ?? "", cmd.group, ...(cmd.keywords ?? [])]
        .join(" ")
        .toLowerCase();
      if (haystack.includes(q)) return 1;
      // Subsequence match keeps "ngstart" → "Start service nginx".
      let i = 0;
      for (const ch of haystack) {
        if (ch === q[i]) i++;
        if (i >= q.length) return 2;
      }
      return Infinity;
    };
    return commands
      .map((cmd) => ({ cmd, s: score(cmd) }))
      .filter((x) => x.s !== Infinity)
      .sort((a, b) => a.s - b.s)
      .slice(0, 30)
      .map((x) => x.cmd);
  }, [commands, query]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setSelected((s) => Math.min(s, Math.max(0, filtered.length - 1)));
    }, 0);
    return () => clearTimeout(timer);
  }, [filtered.length]);

  const run = async (cmd: Command) => {
    onClose();
    // page:/project: navigations the shell handles directly; everything
    // else goes to the backend (services, or events back for panes).
    if (cmd.id.startsWith("page:") || cmd.id.startsWith("project:")) {
      onNavigate(cmd.id);
      return;
    }
    try {
      await RunCommand(cmd.id);
    } catch {
      /* surfaced by the owning controller */
    }
  };

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/50 pt-32"
      onClick={onClose}
    >
      <div
        className="glass w-[560px] max-w-[90vw] overflow-hidden rounded-xl border border-white/15 p-0 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-2 border-b border-white/10 px-3 py-2.5">
          <Search className="h-4 w-4 shrink-0 text-white/40" />
          <input
            ref={inputRef}
            className="w-full bg-transparent text-sm text-white placeholder-white/30 outline-none"
            placeholder={t("commandPalette.placeholder")}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setSelected((s) => Math.min(s + 1, filtered.length - 1));
              } else if (e.key === "ArrowUp") {
                e.preventDefault();
                setSelected((s) => Math.max(s - 1, 0));
              } else if (e.key === "Enter" && filtered[selected]) {
                e.preventDefault();
                void run(filtered[selected]);
              } else if (e.key === "Escape") {
                e.preventDefault();
                onClose();
              }
            }}
          />
          <kbd className="rounded border border-white/15 px-1.5 py-0.5 text-[9px] text-white/40">
            esc
          </kbd>
        </div>
        <div className="max-h-80 overflow-y-auto p-1">
          {filtered.length === 0 && (
            <p className="px-3 py-6 text-center text-xs text-white/40">{t("commandPalette.empty")}</p>
          )}
          {filtered.map((cmd, i) => (
            <button
              key={cmd.id}
              type="button"
              onMouseEnter={() => setSelected(i)}
              onClick={() => void run(cmd)}
              className={`flex w-full items-center gap-2 rounded px-3 py-1.5 text-left text-xs ${
                i === selected ? "bg-accent/25 text-white" : "text-white/70 hover:bg-white/5"
              }`}
            >
              <span className="w-16 shrink-0 text-[9px] uppercase tracking-wide text-white/35">
                {cmd.group}
              </span>
              <span className="shrink-0">{cmd.title}</span>
              {cmd.hint && (
                <span className="min-w-0 flex-1 truncate font-mono text-[10px] text-accent2/80">
                  {cmd.hint}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
